window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4f05be04484f8f8a"]={"versions": [{"id": "FIG-4f05be04484f8f8a", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild eines Simulink-Modellierungsansatzes (Simulink-Modellfenster <code>structure_pattern/Composition to be modeled</code>). Das Diagramm illustriert das kanonische Modellierungsmuster für atomare Software-Komponenten (Atomic Software Components, SW-C) innerhalb einer AUTOSAR-Composition auf Modellierungsebene. Die Komponenten sind als Subsysteme dargestellt, die über standardisierte Port-Klassen mit Bus- und Signalverbindungen angebunden sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei Subsystem-Blöcke:</p>\n<ul class=\"fig-list\"><li><code>Atomic Software Component1</code>: Besitzt Eingangsports <code>RTEEvent</code>, <code>R-Port1</code>, <code>R-Port2</code> sowie Ausgangsports <code>P-Port1</code>, <code>P-Port2</code>.\n</li><li><code>Atomic Software Component2</code>: Besitzt Eingangsports <code>RTEEvent</code>, <code>R-Port1</code>, <code>R-Port2</code> sowie Ausgangsports <code>P-Port1</code>, <code>P-Port2</code>.\n</li></ul>\n<p class=\"fig-p\">Peripherie und Schnittstellen der übergeordneten Composition:</p>\n<ul class=\"fig-list\"><li>Inports für Trigger-Ereignisse:\n<ul class=\"fig-list\"><li>Inport 1 (<code>RTEEvent</code>) für Komponente 1, aufgefächert über einen Bus Selector / De-Mux in <code>&lt;TimingEvent_Runnable1&gt;</code>, <code>&lt;DataReceived_Event_of_DataElement1&gt;</code>, <code>&lt;TimingEvent_Runnable2&gt;</code> und zusammengeführt über Bus Creator / Mux in den Port <code>RTEEvent</code>.\n</li><li>Inport 1 (<code>RTEEvent1</code>) für Komponente 2, aufgefächert in <code>&lt;TimingEvent_Runnable3&gt;</code>, <code>&lt;TimingEvent_Runnable4&gt;</code> und zusammengeführt in den Port <code>RTEEvent</code>.\n</li></ul>\n</li><li>Daten-Inports (R-Ports, Sender/Receiver Communication):\n<ul class=\"fig-list\"><li>Inport 2 (<code>R-Port1</code>) und Inport 3 (<code>R-Port2</code>) an <code>Atomic Software Component1</code>.\n</li><li>Inport 4 (<code>R-Port3</code>) an <code>R-Port1</code> und Inport 5 (<code>R-Port4</code>) an <code>R-Port2</code> von <code>Atomic Software Component2</code>.\n</li></ul>\n</li><li>Daten-Outports (P-Ports, Sender/Receiver Communication):\n<ul class=\"fig-list\"><li>Outport 1 (<code>P-Port1</code>) und Outport 2 (<code>P-Port2</code>) von <code>Atomic Software Component1</code>.\n</li><li>Outport 3 (<code>P-Port3</code>) von <code>P-Port1</code> und Outport 4 (<code>P-Port4</code>) von <code>P-Port2</code> von <code>Atomic Software Component2</code>.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Signalleitungen:</p>\n<ul class=\"fig-list\"><li>Funktionsaufruf-/Event-Verbindungen als gestrichelte Pfeillinien innerhalb der Bus-Selector/Bus-Creator-Struktur.\n</li><li>Datenleitungen als doppelte Balkenlinien (Vektorsignale/Busse) bzw. Einzellinien.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Aperiodische und periodische Aktivierungen treffen als RTEEvents über Inport 1 ein.\n</li><li>Das Event-Bündel wird über Selektoren in spezifische Auslöser für Runnables aufgetrennt (z. B. zeitgesteuerte Ausführung via <code>TimingEvent</code> oder datengetriebene Aktivierung via <code>DataReceived_Event</code>).\n</li><li>Die atomare Software-Komponente empfängt die RTEEvents an ihrem ersten Inport zur internen Steuerung/Triggerung der Runnable Entities.\n</li><li>R-Ports lesen Datenwerte für die Berechnung der Runnables ein.\n</li><li>Nach Durchführung der Berechnungen stellen die P-Ports die Ausgabewerte an die übergeordnete Composition bzw. verbundene Komponenten bereit.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Kanonisches Entwurfsmuster für die Simulink-Modellierung von AUTOSAR Atomic Software Components.\n</li><li>Konvention: Der erste Inport eines Komponenten-Subsystems ist zwingend für das Routing von RTEEvents an die Runnables der Komponente vorgesehen.\n</li><li>Funktionsaufrufe und Events sollten über Bus Selectors und Bus Creators sauber separiert werden, um individuelle Runnables eindeutig anzusteuern.\n</li><li>Alle weiteren Inports bilden die R-Ports und alle Outports die P-Ports für die AUTOSAR Sender/Receiver-Kommunikation ab.\n</li><li>Komponenten können wahlweise als virtuelle/nicht-virtuelle Subsysteme, Library-Blöcke oder Model-Reference-Blöcke ausgeführt sein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-93e5b92784d11026", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild eines Simulink-Modellierungsansatzes (Simulink-Modellfenster <code>structure_pattern/Composition to be modeled</code>). Das Diagramm illustriert das kanonische Modellierungsmuster für atomare Software-Komponenten (Atomic Software Components, SW-C) innerhalb einer AUTOSAR-Composition auf Modellierungsebene. Die Komponenten sind als Subsysteme dargestellt, die über standardisierte Port-Klassen mit Bus- und Signalverbindungen angebunden sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei Subsystem-Blöcke:</p>\n<ul class=\"fig-list\"><li><code>Atomic Software Component1</code>: Besitzt Eingangsports <code>RTEEvent</code>, <code>R-Port1</code>, <code>R-Port2</code> sowie Ausgangsports <code>P-Port1</code>, <code>P-Port2</code>.\n</li><li><code>Atomic Software Component2</code>: Besitzt Eingangsports <code>RTEEvent</code>, <code>R-Port1</code>, <code>R-Port2</code> sowie Ausgangsports <code>P-Port1</code>, <code>P-Port2</code>.\n</li></ul>\n<p class=\"fig-p\">Peripherie und Schnittstellen der übergeordneten Composition:</p>\n<ul class=\"fig-list\"><li>Inports für Trigger-Ereignisse:\n<ul class=\"fig-list\"><li>Inport 1 (<code>RTEEvent</code>) für Komponente 1, aufgefächert über einen Bus Selector / De-Mux in <code>&lt;TimingEvent_Runnable1&gt;</code>, <code>&lt;DataReceived_Event_of_DataElement1&gt;</code>, <code>&lt;TimingEvent_Runnable2&gt;</code> und zusammengeführt über Bus Creator / Mux in den Port <code>RTEEvent</code>.\n</li><li>Inport 1 (<code>RTEEvent1</code>) für Komponente 2, aufgefächert in <code>&lt;TimingEvent_Runnable3&gt;</code>, <code>&lt;TimingEvent_Runnable4&gt;</code> und zusammengeführt in den Port <code>RTEEvent</code>.\n</li></ul>\n</li><li>Daten-Inports (R-Ports, Sender/Receiver Communication):\n<ul class=\"fig-list\"><li>Inport 2 (<code>R-Port1</code>) und Inport 3 (<code>R-Port2</code>) an <code>Atomic Software Component1</code>.\n</li><li>Inport 4 (<code>R-Port3</code>) an <code>R-Port1</code> und Inport 5 (<code>R-Port4</code>) an <code>R-Port2</code> von <code>Atomic Software Component2</code>.\n</li></ul>\n</li><li>Daten-Outports (P-Ports, Sender/Receiver Communication):\n<ul class=\"fig-list\"><li>Outport 1 (<code>P-Port1</code>) und Outport 2 (<code>P-Port2</code>) von <code>Atomic Software Component1</code>.\n</li><li>Outport 3 (<code>P-Port3</code>) von <code>P-Port1</code> und Outport 4 (<code>P-Port4</code>) von <code>P-Port2</code> von <code>Atomic Software Component2</code>.\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Signalleitungen:</p>\n<ul class=\"fig-list\"><li>Funktionsaufruf-/Event-Verbindungen als gestrichelte Pfeillinien innerhalb der Bus-Selector/Bus-Creator-Struktur.\n</li><li>Datenleitungen als doppelte Balkenlinien (Vektorsignale/Busse) bzw. Einzellinien.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Aperiodische und periodische Aktivierungen treffen als RTEEvents über Inport 1 ein.\n</li><li>Das Event-Bündel wird über Selektoren in spezifische Auslöser für Runnables aufgetrennt (z. B. zeitgesteuerte Ausführung via <code>TimingEvent</code> oder datengetriebene Aktivierung via <code>DataReceived_Event</code>).\n</li><li>Die atomare Software-Komponente empfängt die RTEEvents an ihrem ersten Inport zur internen Steuerung/Triggerung der Runnable Entities.\n</li><li>R-Ports lesen Datenwerte für die Berechnung der Runnables ein.\n</li><li>Nach Durchführung der Berechnungen stellen die P-Ports die Ausgabewerte an die übergeordnete Composition bzw. verbundene Komponenten bereit.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Kanonisches Entwurfsmuster für die Simulink-Modellierung von AUTOSAR Atomic Software Components.\n</li><li>Konvention: Der erste Inport eines Komponenten-Subsystems ist zwingend für das Routing von RTEEvents an die Runnables der Komponente vorgesehen.\n</li><li>Funktionsaufrufe und Events sollten über Bus Selectors und Bus Creators sauber separiert werden, um individuelle Runnables eindeutig anzusteuern.\n</li><li>Alle weiteren Inports bilden die R-Ports und alle Outports die P-Ports für die AUTOSAR Sender/Receiver-Kommunikation ab.\n</li><li>Komponenten können wahlweise als virtuelle/nicht-virtuelle Subsysteme, Library-Blöcke oder Model-Reference-Blöcke ausgeführt sein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4f05be04484f8f8a", "to": "FIG-93e5b92784d11026", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
